        { group: "thinking of", start: 82.370, end: 85.820, ipa: "/aɪm ˈθɪŋkɪŋ ʌv ˈɡoʊɪŋ ɑːn ə ˈwɜːrkɪŋ ˈhɑːlədeɪ/", trans: "워킹홀리데이 갈까 생각 중이야.", chunks: [{ text: "I'm thinking of going on a working holiday.", s: 82.370, e: 85.820 }] }
