        { group: "skip", start: 62.910, end: 65.650, ipa: "/aɪ ˈjuːʒuəli skɪp ˈbrɛkfəst/", trans: "난 보통 아침을 걸러.", chunks: [{ text: "I usually skip breakfast.", s: 62.910, e: 65.650 }] },
        { group: "skip", start: 68.650, end: 72.220, ipa: "/ˈnɛvər skɪp ðə laɪv klæs wɪð ˈkoʊhɛm/", trans: "코햄과의 라이브 클래스는 절대 빠지지 마.", chunks: [{ text: "Never skip the live class with Koham.", s: 68.650, e: 72.220 }] },
        { group: "skip", start: 75.580, end: 79.500, ipa: "/lɛts skɪp ðɪs pɑːrt ænd ɡoʊ tuː ðə nɛkst peɪdʒ/", trans: "이 부분은 넘어가고 다음 페이지로 가자.", chunks: [{ text: "Let's skip this part and go to the next page.", s: 75.580, e: 79.500 }] },
        { group: "recently / lately", start: 83.650, end: 87.050, ipa: "/aɪ ˈriːsəntli dʒɔɪnd æn ˈɪŋɡlɪʃ ˈbuːtˌkæmp/", trans: "나 최근에 영어 부트캠프 시작했어.", chunks: [{ text: "I recently joined an English bootcamp.", s: 83.650, e: 87.050 }] },
        { group: "recently / lately", start: 90.430, end: 93.910, ipa: "/ˈriːsəntli, aɪ mɛt ˈsʌmwʌn ɑːn ˈtɪndər/", trans: "나 최근에 틴더에서 누구 만났어.", chunks: [{ text: "Recently, I met someone on Tinder.", s: 90.430, e: 93.910 }] },
        { group: "recently / lately", start: 97.380, end: 101.010, ipa: "/hæv juː siːn ˈɛni ɡʊd ˈmuːviz ˈriːsəntli/", trans: "최근에 재밌는 영화 본 거 있어?", chunks: [{ text: "Have you seen any good movies recently?", s: 97.380, e: 101.010 }] },
        { group: "Why don't you/we", start: 104.580, end: 107.570, ipa: "/waɪ doʊnt juː teɪk ə breɪk/", trans: "좀 쉬는 게 어때?", chunks: [{ text: "Why don't you take a break?", s: 104.580, e: 107.570 }] },
        { group: "Why don't you/we", start: 110.570, end: 113.410, ipa: "/waɪ doʊnt wiː ɡoʊ fɔːr ə wɔːk/", trans: "우리 산책하러 갈래?", chunks: [{ text: "Why don't we go for a walk?", s: 110.570, e: 113.410 }] },
        { group: "Why don't you/we", start: 116.190, end: 118.770, ipa: "/waɪ doʊnt juː æsk hɪm aʊt/", trans: "걔한테 데이트 신청해 보는 게 어때?", chunks: [{ text: "Why don't you ask him out?", s: 116.190, e: 118.770 }] },
        { group: "worth it", start: 121.670, end: 125.250, ipa: "/ðæt haɪk wʌz ˈrɪəli hɑːrd, bʌt ɪt wʌz wɜːrθ ɪt/", trans: "등산은 정말 힘들었지만, 그럴 만한 가치가 있었어.", chunks: [{ text: "That hike was really hard, but it was worth it.", s: 121.670, e: 125.250 }] },
        { group: "worth it", start: 129.120, end: 131.780, ipa: "/ðæt ˈmuːvi ˈwʌzənt wɜːrθ ɪt/", trans: "그 영화는 (돈/시간) 아까웠어.", chunks: [{ text: "That movie wasn't worth it.", s: 129.120, e: 131.780 }] },
        { group: "worth it", start: 134.550, end: 137.490, ipa: "/ðə ˈbuːtˌkæmp wʌz ˈtoʊtəli wɜːrθ ɪt/", trans: "부트캠프는 완전 그럴 만한 가치가 있었어.", chunks: [{ text: "The bootcamp was totally worth it.", s: 134.550, e: 137.490 }] }
